BEGIN;CREATE TABLE IF NOT EXISTS trust_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,assignment_id uuid REFERENCES work_assignments(id) ON DELETE CASCADE,professional_id uuid REFERENCES professional_profiles(id) ON DELETE CASCADE,event_type text NOT NULL CHECK(event_type IN('no_show','late_arrival','incident','commendation')),occurred_at timestamptz NOT NULL DEFAULT now(),notes text,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS trust_events_professional_idx ON trust_events(professional_id,occurred_at DESC);ALTER TABLE trust_events ENABLE ROW LEVEL SECURITY;ALTER TABLE trust_events FORCE ROW LEVEL SECURITY;CREATE POLICY trust_events_tenant_isolation ON trust_events USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON trust_events TO app_runtime;COMMIT;
